import{f as e,j as t,m as n}from"./runtime-core.esm-bundler-DBPRRnSd.js";import{t as r}from"./plugin-vue_export-helper-CDQIAITX.js";var i=JSON.parse(`{"path":"/notes/%E9%9D%A2%E8%AF%95/java-%E9%9B%86%E5%90%88/","title":"Java集合 | notes","lang":"zh-CN","frontmatter":{"title":"Java集合","createTime":"2026/04/04 23:28:20","permalink":"/notes/面试/java-集合/","description":"[TOC] 有哪些集合类？ Java 中有哪些集合类？请简单介绍 - Java 集合面试题 - 面试鸭 - 程序员求职面试刷题神器 Java 中的 LinkedHashMap 是什么？ - Java 集合面试题 - 面试鸭 - 程序员求职面试刷题神器 Java 中的 List 接口有哪些实现类？ - Java 集合面试题 - 面试鸭 - 程序员求职面试...","head":[["script",{"type":"application/ld+json"},"{\\"@context\\":\\"https://schema.org\\",\\"@type\\":\\"Article\\",\\"headline\\":\\"Java集合\\",\\"image\\":[\\"\\"],\\"dateModified\\":\\"2026-06-25T07:15:35.000Z\\",\\"author\\":[]}"],["meta",{"property":"og:url","content":"http://xiaofei.site/notes/%E9%9D%A2%E8%AF%95/java-%E9%9B%86%E5%90%88/"}],["meta",{"property":"og:site_name","content":"计算机知识杂货铺"}],["meta",{"property":"og:title","content":"Java集合"}],["meta",{"property":"og:description","content":"[TOC] 有哪些集合类？ Java 中有哪些集合类？请简单介绍 - Java 集合面试题 - 面试鸭 - 程序员求职面试刷题神器 Java 中的 LinkedHashMap 是什么？ - Java 集合面试题 - 面试鸭 - 程序员求职面试刷题神器 Java 中的 List 接口有哪些实现类？ - Java 集合面试题 - 面试鸭 - 程序员求职面试..."}],["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:locale","content":"zh-CN"}],["meta",{"property":"og:updated_time","content":"2026-06-25T07:15:35.000Z"}],["meta",{"property":"article:modified_time","content":"2026-06-25T07:15:35.000Z"}]]},"readingTime":{"minutes":9.46,"words":2838},"git":{"createdTime":1775331561000,"updatedTime":1782371735000,"contributors":[{"name":"xiaofei","username":"xiaofei","email":"tu_aofei@163.com","commits":1,"avatar":"https://avatars.githubusercontent.com/u/49927991?s=96&v=4","url":"https://github.com/731016"},{"name":"731016","username":"731016","email":"xiaofei00152@gmail.com","commits":1,"avatar":"https://avatars.githubusercontent.com/731016?v=4","url":"https://github.com/731016"}],"changelog":[{"hash":"6226c1c3cfce235348f612b9ec8a011caac82791","time":1782371735000,"email":"xiaofei00152@gmail.com","author":"731016","message":"更新侧边栏配置和图标"},{"hash":"fb8bc3afbb338138170b503192cbdb88a45075bd","time":1775331561000,"email":"tu_aofei@163.com","author":"xiaofei","message":"更新为vuepress"}]},"autoDesc":true,"filePathRelative":"notes/面试/Java集合.md","headers":[],"bulletin":true}`),a={name:`Java集合.md`};function o(r,i,a,o,s,c){return t(),e(`div`,null,[...i[0]||=[n(`<p>[TOC]</p><h2 id="有哪些集合类" tabindex="-1"><a class="header-anchor" href="#有哪些集合类"><span>有哪些集合类？</span></a></h2><p><a href="https://www.mianshiya.com/bank/1788408712975282177/question/1780933294699868162#heading-3" target="_blank" rel="noopener noreferrer">Java 中有哪些集合类？请简单介绍 - Java 集合面试题 - 面试鸭 - 程序员求职面试刷题神器</a></p><p><a href="https://www.mianshiya.com/bank/1788408712975282177/question/1780933294783754241#heading-0" target="_blank" rel="noopener noreferrer">Java 中的 LinkedHashMap 是什么？ - Java 集合面试题 - 面试鸭 - 程序员求职面试刷题神器</a></p><p><a href="https://www.mianshiya.com/bank/1788408712975282177/question/1780933294708256769#heading-1" target="_blank" rel="noopener noreferrer">Java 中的 List 接口有哪些实现类？ - Java 集合面试题 - 面试鸭 - 程序员求职面试刷题神器</a></p><p><a href="https://www.mianshiya.com/bank/1788408712975282177/question/1780933294796337153" target="_blank" rel="noopener noreferrer">Java 中的 TreeMap 是什么？ - Java 集合面试题 - 面试鸭 - 程序员求职面试刷题神器</a></p><p>Collection接口：存储对象集合类</p><p><strong>List接口</strong></p><p>ArrayList：动态数组，查询快，插入删除慢</p><p>LinkedList：双向链表，查询慢，插入删除快</p><p>Vector：线程安全的动态数组，类似ArrayList</p><p><strong>Set接口</strong></p><p>HashSet：哈希表，无序，不重复</p><p>LinkedHashSet：链表+哈希表，维护插入顺序，不重复</p><p>TreeSet：基于红黑树，有序，不重复</p><p><strong>Queue接口</strong></p><p>LinkedList：作为队列使用，支持FIFO（先进先出）</p><p>PriorityQueue：优先堆，自然排序或指定比较器排序</p><p><strong>Map接口</strong>：key-value键值对</p><p>hashMap：哈希表，无需，key不重复</p><p>LinkedHashMap：链表+哈希表，维护插入顺序，key不重复</p><p>TreeMap：红黑树，键值对有序，key不重复，key不能为null</p><p>ConcurrentHashMap：线程安全的哈希表，key和值不能为null</p><h2 id="数组和链表的区别" tabindex="-1"><a class="header-anchor" href="#数组和链表的区别"><span>数组和链表的区别</span></a></h2><p><a href="https://www.mianshiya.com/bank/1788408712975282177/question/1780933294704062466#heading-1" target="_blank" rel="noopener noreferrer">数组和链表在 Java 中的区别是什么？ - Java 集合面试题 - 面试鸭 - 程序员求职面试刷题神器</a></p><p><a href="https://www.mianshiya.com/bank/1788408712975282177/question/1839516705798356994" target="_blank" rel="noopener noreferrer">Java 中 ArrayList 和 LinkedList 有什么区别？ - Java 集合面试题 - 面试鸭 - 程序员求职面试刷题神器</a></p><p><strong>数组</strong></p><p>大小固定的连续存储空间</p><p>长度固定，扩展数组需要重新分配新的空间</p><p>可直接用下标访问</p><p><strong>链表</strong></p><p>不需要连续存储空间</p><p>扩展只需要使用指针存储新的地址空间，扩展方便</p><p>需要从头节点开始查找</p><p>额外占用空间存储指针，占用空间比数组大</p><h2 id="hashmap原理" tabindex="-1"><a class="header-anchor" href="#hashmap原理"><span>hashMap原理</span></a></h2><p><a href="https://www.mianshiya.com/bank/1788408712975282177/question/1834107117591187457" target="_blank" rel="noopener noreferrer">说说 Java 中 HashMap 的原理？ - Java 集合面试题 - 面试鸭 - 程序员求职面试刷题神器</a></p><p><a href="https://www.mianshiya.com/bank/1788408712975282177/question/1821510409319555074" target="_blank" rel="noopener noreferrer">使用 HashMap 时，有哪些提升性能的技巧？ - Java 集合面试题 - 面试鸭 - 程序员求职面试刷题神器</a></p><p><a href="https://www.mianshiya.com/bank/1788408712975282177/question/1821481519536611330" target="_blank" rel="noopener noreferrer">什么是 Hash 碰撞？怎么解决哈希碰撞？ - Java 集合面试题 - 面试鸭 - 程序员求职面试刷题神器</a></p><p>HashMap是基于哈希表的数据结构，用于存储键值对。将键的hash值映射到数组索引位置，通过数组+链表（jdk1.8以后是<strong>数组+链表+红黑树</strong>）来处理哈希冲突。</p><p>使用<code>hashcode()</code>计算hash值，通过indexFor()（jdk1.8以后使用<code>（n-1）&amp; hash</code>）确定元素在数组中的存储位置。</p><p>默认初始容量16，负载因子0.75。当存储元素数量超过16 * 0.75 = 12 个时，触发扩容操作，容量 * 2 并重新分配元素位置。</p><p>优化当多个元素映射到同一个哈希桶时的查找性能，当链表长度&gt;8，链表会转变为红黑树（自平衡二叉树）。树中元素&lt;6，会转换回链表</p><p>jdk1.7之前链表插入使用头插法，发生hash冲突时，新节点总是插入到链表头部；在多线程环境下，可能形成环，特别是在并发扩容时</p><p>jdk1.8，改为尾插法，保持插入顺序</p><p>元素数量 &gt; 容量 * 负载因子，触发扩容 * 2，会从新计算所有键的索引，耗时操作</p><ul><li>确定一个初始大小</li><li>调整负载因子</li><li>hashcode均匀分布</li></ul><p>保留插入顺序，使用LinkedHashMap</p><p>保证有序，使用TreeMap</p><p>线程安全，使用ConcurrentHashMap</p><p>hashcode冲突</p><ul><li>使用链表存储</li><li>开放寻址</li><li>重新计算hashcode</li></ul><h2 id="concurrenthashmap1-7和1-8的区别" tabindex="-1"><a class="header-anchor" href="#concurrenthashmap1-7和1-8的区别"><span>concurrentHashMap1.7和1.8的区别</span></a></h2><p><a href="https://www.mianshiya.com/bank/1788408712975282177/question/1780933294813114369#heading-2" target="_blank" rel="noopener noreferrer">Java 中 ConcurrentHashMap 1.7 和 1.8 之间有哪些区别？ - Java 集合面试题 - 面试鸭 - 程序员求职面试刷题神器</a></p><p><a href="https://www.mianshiya.com/question/1780933295027023873" target="_blank" rel="noopener noreferrer">什么是 Java 的 CAS（Compare-And-Swap）操作？ - 面试鸭 - 程序员求职面试刷题神器</a></p><p><strong>1.7</strong></p><p>使用分段锁，每一个segment是独立的，可并发访问，默认16</p><p>多个segment组成，每个segment包含一个hashmap。单独扩容</p><p>不加锁，三次获取有变化，重新加锁获取</p><p><strong>1.8</strong></p><p>移除segment，只在更新链表或红黑树节点使用synchronized锁住链表或树的头节点</p><p>增加红黑树</p><p>扩容整个hashmap，通过CAS操作确保线程安全，多个线程可逐步同时扩容</p><p>使用数组维护节点数量，使用CAS修改basecount，失败就选择countercell对象修改，basecount + 所有countercell</p><h2 id="concurrenthashmap的get方法是否需要加锁" tabindex="-1"><a class="header-anchor" href="#concurrenthashmap的get方法是否需要加锁"><span>concurrentHashMap的get方法是否需要加锁？</span></a></h2><p><a href="https://www.mianshiya.com/bank/1788408712975282177/question/1780933294829891585#heading-3" target="_blank" rel="noopener noreferrer">Java 中 ConcurrentHashMap 的 get 方法是否需要加锁？ - Java 集合面试题 - 面试鸭 - 程序员求职面试刷题神器</a></p><p>使用volatile，保证写入时，就算读取也能获取最新的数据</p><h2 id="concurrenthashmap不支持key或value为空" tabindex="-1"><a class="header-anchor" href="#concurrenthashmap不支持key或value为空"><span>concurrentHashMap不支持key或value为空？</span></a></h2><p><a href="https://www.mianshiya.com/bank/1788408712975282177/question/1780933294834085890" target="_blank" rel="noopener noreferrer">为什么 Java 的 ConcurrentHashMap 不支持 key 或 value 为 null？ - Java 集合面试题 - 面试鸭 - 程序员求职面试刷题神器</a></p><p>避免混淆，并发环境下，如果通过key获取value1为空，就不清楚真的是空还是值是空的情况</p><h2 id="hashmap和hashtable的区别" tabindex="-1"><a class="header-anchor" href="#hashmap和hashtable的区别"><span>HashMap和HashTable的区别</span></a></h2><p><a href="https://www.mianshiya.com/bank/1788408712975282177/question/1780933294720839681" target="_blank" rel="noopener noreferrer">Java 中的 HashMap 和 Hashtable 有什么区别？ - Java 集合面试题 - 面试鸭 - 程序员求职面试刷题神器</a></p><table><thead><tr><th></th><th>线程安全</th><th>性能差异</th><th>允许空值</th><th>继承结构</th><th>迭代器类型</th></tr></thead><tbody><tr><td>hashMap</td><td>❌</td><td>单线程环境下优于hashTable</td><td>1个nul key，多个null值</td><td>AbstractMap，Map的实现类</td><td>快速失败的Iterator</td></tr><tr><td>hashTable</td><td>✅synchronized</td><td>低于hashMap</td><td>不允许null key和值</td><td>Dictionary</td><td>弱一致性的Enumerator</td></tr></tbody></table><p>ConcurrentHashMap是HashTable的替代方案。通过分段锁提高了并发性能，读无锁，写使用局部分段锁</p><h2 id="concurrenthashmap和hashtable的区别" tabindex="-1"><a class="header-anchor" href="#concurrenthashmap和hashtable的区别"><span>ConcurrentHashMap和HashTable的区别</span></a></h2><p><a href="https://www.mianshiya.com/bank/1788408712975282177/question/1854745940761190402" target="_blank" rel="noopener noreferrer">ConcurrentHashMap 和 Hashtable 的区别是什么？ - Java 集合面试题 - 面试鸭 - 程序员求职面试刷题神器</a></p><p>都是线程安全的哈希表实现</p><p>hashtable：使用单一的synchronized锁对整个哈希表进行同步，效率低下</p><p>ConcurrentHashMap：CAS + synchronized 实现，如果node为空，使用cas将数据插入节点，如果不为空，使用synchronized锁定node的头节点</p><h2 id="hashset和hashmap的区别" tabindex="-1"><a class="header-anchor" href="#hashset和hashmap的区别"><span>hashset和hashmap的区别</span></a></h2><p><a href="https://www.mianshiya.com/bank/1788408712975282177/question/1780933294729228289#heading-2" target="_blank" rel="noopener noreferrer">Java 中的 HashSet 和 HashMap 有什么区别？ - Java 集合面试题 - 面试鸭 - 程序员求职面试刷题神器</a></p><p>hashset内部使用hashmap实现，hashset中的元素实际存储在hashmap的key中，value都是一个常量对象PRESENT</p><h2 id="copyonwritearraylist和collections-synchronizedlist-的区别" tabindex="-1"><a class="header-anchor" href="#copyonwritearraylist和collections-synchronizedlist-的区别"><span>CopyOnWriteArrayList和Collections.synchronizedList()的区别</span></a></h2><p><a href="https://www.mianshiya.com/bank/1788408712975282177/question/1821470164721016833#heading-0" target="_blank" rel="noopener noreferrer">Java 的 CopyOnWriteArrayList 和 Collections.synchronizedList 有什么区别？分别有什么优缺点？ - Java 集合面试题 - 面试鸭 - 程序员求职面试刷题神器</a></p><p><a href="https://www.mianshiya.com/bank/1788408712975282177/question/1780933294838280194#heading-4" target="_blank" rel="noopener noreferrer">Java 中的 CopyOnWriteArrayList 是什么？ - Java 集合面试题 - 面试鸭 - 程序员求职面试刷题神器</a></p><p><strong>CopyOnWriteArrayList</strong></p><p>线程安全的List实现，特性：<strong>写时复制</strong></p><p>增删改操作会复制一个新的底层数组。读操作不加锁（volatile 修饰的数组），写操作加锁</p><p>合适<strong>读多写少</strong></p><p><strong>Collections.synchronizedList()</strong></p><p>一个包装方法，将任何List转换为线程安全的版本，对增删改查使用synchronized进行同步，保证线程安全</p><p>适合<strong>临时</strong>转换为线程安全的List使用</p><h2 id="arraylist扩容机制" tabindex="-1"><a class="header-anchor" href="#arraylist扩容机制"><span>ArrayList扩容机制</span></a></h2><p><a href="https://www.mianshiya.com/bank/1788408712975282177/question/1839515038747066370#heading-0" target="_blank" rel="noopener noreferrer">Java ArrayList 的扩容机制是什么？ - Java 集合面试题 - 面试鸭 - 程序员求职面试刷题神器</a></p><p>默认大小10，超过当前容量，触发扩展机制，创建新数组大小为原来的1.5倍（<code>int newCapacity = oldCapacity + (oldCapacity &gt;&gt; 1);</code>）使用copyOf()将原数组复制到新数组</p><h2 id="hashmap的扩容机制" tabindex="-1"><a class="header-anchor" href="#hashmap的扩容机制"><span>HashMap的扩容机制</span></a></h2><p><a href="https://www.mianshiya.com/bank/1788408712975282177/question/1780933294750199809#heading-2" target="_blank" rel="noopener noreferrer">Java 中 HashMap 的扩容机制是怎样的？ - Java 集合面试题 - 面试鸭 - 程序员求职面试刷题神器</a></p><p><a href="https://www.mianshiya.com/bank/1795650132375805954/question/1797473188553293825#heading-1" target="_blank" rel="noopener noreferrer">假设有一个 1G 大的 HashMap，此时用户请求过来刚好触发它的扩容，会怎样？让你改造下 HashMap 的实现该怎样优化？ - 后端场景面试题 - 面试鸭 - 程序员求职面试刷题神器</a></p><p>基于负载因子决定。默认为0.75</p><p>默认扩容原大小的2次方，即2倍</p><p>在扩容时，并不是所有元素都需要重新计算哈希码。由于数组长度变为原来的两倍，新的数组索引计算方式为：</p><div class="language-java line-numbers-mode" data-highlighter="shiki" data-ext="java" style="--shiki-light:#393a34;--shiki-dark:#dbd7caee;--shiki-light-bg:#ffffff;--shiki-dark-bg:#121212;"><pre class="shiki shiki-themes vitesse-light vitesse-dark vp-code"><code class="language-java"><span class="line"><span style="--shiki-light:#AB5959;--shiki-dark:#CB7676;">int</span><span style="--shiki-light:#B07D48;--shiki-dark:#BD976A;"> newIndex</span><span style="--shiki-light:#999999;--shiki-dark:#666666;"> =</span><span style="--shiki-light:#999999;--shiki-dark:#666666;"> (</span><span style="--shiki-light:#B07D48;--shiki-dark:#BD976A;">newTable</span><span style="--shiki-light:#999999;--shiki-dark:#666666;">.</span><span style="--shiki-light:#B07D48;--shiki-dark:#BD976A;">length</span><span style="--shiki-light:#AB5959;--shiki-dark:#CB7676;"> -</span><span style="--shiki-light:#2F798A;--shiki-dark:#4C9A91;"> 1</span><span style="--shiki-light:#999999;--shiki-dark:#666666;">)</span><span style="--shiki-light:#AB5959;--shiki-dark:#CB7676;"> &amp;</span><span style="--shiki-light:#393A34;--shiki-dark:#DBD7CAEE;"> hash</span><span style="--shiki-light:#999999;--shiki-dark:#666666;">;</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>对于原来的哈希值<code>hash</code>，如果<code>(hash &amp; oldCap) == 0</code>，那么在新数组中的索引位置不变；如果<code>(hash &amp; oldCap)!= 0</code>，那么在新数组中的索引位置是原来的索引位置加上旧数组的容量。</p><p>这是因为数组长度翻倍后，新的索引计算实际上是在原来的基础上增加了一位判断。例如，假设原来数组长度为 8（二进制为<code>1000</code>），新数组长度为 16（二进制为<code>10000</code>）。原来的索引计算是<code>hash &amp; 0111</code>，新的索引计算是<code>hash &amp; 1111</code>。如果<code>hash</code>的第 4 位（从右往左，第 0 位是最低位）为 0，那么新的索引与原来相同；如果第 4 位为 1，那么新的索引就是原来的索引加上 8。</p><h2 id="hashmap扩容时使用2的n次方" tabindex="-1"><a class="header-anchor" href="#hashmap扩容时使用2的n次方"><span>hashmap扩容时使用2的n次方？</span></a></h2><p><a href="https://www.mianshiya.com/bank/1788408712975282177/question/1780933294754394113" target="_blank" rel="noopener noreferrer">为什么 HashMap 在 Java 中扩容时采用 2 的 n 次方倍？ - Java 集合面试题 - 面试鸭 - 程序员求职面试刷题神器</a></p><p>通过(n-1)&amp;hash计算元素的存储索引位置，只有在数组容量是n^2才能确保索引均匀分布。<strong>位运算的效率高于取模运算</strong>，提高了hash运算的效率</p><p>i = (n-1)&amp;hash，满足这个公式，当b=2的n次幂是，a%b = a&amp;(b-1)</p><h2 id="hashmap负载因子默认0-75" tabindex="-1"><a class="header-anchor" href="#hashmap负载因子默认0-75"><span>hashmap负载因子默认0.75？</span></a></h2><p><a href="https://www.mianshiya.com/bank/1788408712975282177/question/1780933294758588418#heading-0" target="_blank" rel="noopener noreferrer">为什么 Java 中 HashMap 的默认负载因子是 0.75？ - Java 集合面试题 - 面试鸭 - 程序员求职面试刷题神器</a></p><p>时间复杂度和空间复杂度度的合理平衡</p><p>高并发读取场景：0.5空间利用率低，hash冲突少，查找效率高，频繁扩容</p><p>内存受限场景：1.0空间利用率高，哈希冲突概率大，降低查找效率</p><h2 id="为什么jdk1-8对hashmap进行了红黑树的改动" tabindex="-1"><a class="header-anchor" href="#为什么jdk1-8对hashmap进行了红黑树的改动"><span>为什么jdk1.8对hashmap进行了红黑树的改动？</span></a></h2><p><a href="https://www.mianshiya.com/bank/1788408712975282177/question/1780933294771171329#heading-0" target="_blank" rel="noopener noreferrer">为什么 JDK 1.8 对 HashMap 进行了红黑树的改动？ - Java 集合面试题 - 面试鸭 - 程序员求职面试刷题神器</a></p><p><a href="https://www.mianshiya.com/bank/1788408712975282177/question/1780933294775365634" target="_blank" rel="noopener noreferrer">JDK 1.8 对 HashMap 除了红黑树还进行了哪些改动？ - Java 集合面试题 - 面试鸭 - 程序员求职面试刷题神器</a></p><p>1.8之前使用链表解决hash冲突。当哈希冲突较多时，链表元素增多，查找、插入和删除的时间复杂度从O(1)-&gt;O(n)</p><p>使用红黑树，当数组长度&gt;=64,链表长度&gt;=8时，链表转化为红黑树；链表长度&lt;6时，重新转换为链表；平衡二叉树，时间复杂度O(log n)</p><p>避免频繁树化，减少内存占用（红黑树需要额外指针和结构，红黑树节点大小是普通节点大小的两倍）</p><p>优化hash计算：扰动函数</p><p>扩容机制优化：不是所有元素都重新计算hashcode</p><p>头插法变为尾插法：避免多线程扩容操作出现环</p>`,122)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};